# ---------------------------------------------------------------------------
# Null / NaN edge cases
# ---------------------------------------------------------------------------

def test_chart_with_null_x_column_renders():
    """Chart with some null values in x-encoded column should render without crash."""
    df = pl.DataFrame({"x": [1.0, None, 3.0], "y": [1.0, 2.0, 3.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_chart_with_null_y_column_renders():
    """Chart with some null values in y-encoded column should render without crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, None, 3.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_chart_with_null_color_column_renders():
    """Chart with null values in a color encoding column should render without crash."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, 2.0, 3.0], "c": ["a", None, "b"]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y", color="c").show_svg()
    assert "<svg" in svg


def test_displot_with_null_x_column():
    """displot on a column with nulls should not raise and should produce valid SVG."""
    df = pl.DataFrame({"x": [1.0, None, 2.0, 3.0, None, 4.0]})
    svg = fr.displot(df, x="x").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


