def test_chart_zero_row_df_renders_empty_axes():  # BUG: ValueError: empty record batch stream — zero-row DataFrame crashes renderer instead of producing empty axes
    """A zero-row DataFrame should produce SVG with axes but no marks."""
    df = pl.DataFrame({"x": pl.Series([], dtype=pl.Float64), "y": pl.Series([], dtype=pl.Float64)})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
    assert "<svg" in svg


def test_displot_zero_row_df_does_not_raise():  # BUG: ValueError: empty record batch stream — zero-row displot crashes renderer
    """displot on a zero-row DataFrame should not raise."""
    df = pl.DataFrame({"x": pl.Series([], dtype=pl.Float64)})
    svg = fr.displot(df, x="x").show_svg()
    assert "<svg" in svg


def test_catplot_zero_row_df_does_not_raise():  # BUG: ValueError: empty record batch stream — zero-row catplot crashes renderer
    """catplot on a zero-row DataFrame should not raise."""
    df = pl.DataFrame({
        "group": pl.Series([], dtype=pl.Utf8),
        "val": pl.Series([], dtype=pl.Float64),
    })
    svg = fr.catplot(df, x="group", y="val", kind="strip").show_svg()
    assert "<svg" in svg


def test_heatmap_zero_row_raises_or_renders():
    """heatmap on a zero-row DataFrame should either raise ValueError or produce SVG."""
    df = pl.DataFrame({
        "row": pl.Series([], dtype=pl.Utf8),
        "A": pl.Series([], dtype=pl.Float64),
    })
    try:
        svg = fr.heatmap(df).show_svg()
        assert "<svg" in svg
    except (ValueError, Exception):
        pass  # acceptable — empty data is a degenerate input


