def test_chart_single_row_renders():
    """A one-row DataFrame should produce valid SVG with no crash."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
