def test_chart_all_identical_x_values_renders():
    """Degenerate domain (all x identical) should not produce NaN in path d attributes."""
    df = pl.DataFrame({"x": [3.0, 3.0, 3.0, 3.0], "y": [1.0, 2.0, 3.0, 4.0]})
    svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
