# ---------------------------------------------------------------------------
# Error contract tests
# ---------------------------------------------------------------------------

def test_mark_base_rejects_unknown_kwarg():
    """mark_point with an unknown kwarg should raise TypeError with a legible message."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    with pytest.raises(TypeError, match="unknown keyword argument"):
        fr.Chart(df).mark_point(not_a_real_kwarg=99)


def test_encode_rejects_unknown_channel():
    """encode with an unknown channel name should raise ValueError."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    with pytest.raises(ValueError, match="unknown encoding channel"):
        fr.Chart(df).mark_point().encode(x="x", not_a_channel="y")


def test_encode_rejects_non_string_non_channel():
    """encode with a bare integer should raise TypeError, not silently accept it."""
    df = pl.DataFrame({"x": [1.0], "y": [2.0]})
    with pytest.raises(TypeError):
        fr.Chart(df).mark_point().encode(x=42)


def test_mark_shap_waterfall_sentinel_raises():
    """mark_shap_waterfall without explicit sample_idx raises ValueError immediately."""
    df = pl.DataFrame({"feature": ["a"], "shap_value": [0.5]})
    with pytest.raises(ValueError, match="sample_idx"):
        fr.Chart(df).mark_shap_waterfall()


def test_catplot_native_scale_raises():
    """catplot(native_scale=True) should raise ValueError."""
    df = pl.DataFrame({"group": ["a", "b"], "val": [1.0, 2.0]})
    with pytest.raises(ValueError, match="native_scale"):
        fr.catplot(df, x="group", y="val", native_scale=True)


def test_displot_invalid_multiple_raises():
    """displot with an unknown multiple should raise ValueError."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0]})
    with pytest.raises(ValueError, match="multiple"):
        fr.displot(df, x="x", multiple="interleave")


def test_displot_ecdf_without_x_raises():
    """displot(kind='ecdf') without x= should raise ValueError."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0]})
    with pytest.raises(ValueError):
        fr.displot(df, kind="ecdf")


