def test_chart_add_operator_produces_valid_svg(small_df):
    """Chart + Chart composition should produce SVG with no NaN in path d attrs."""
    scatter = fr.Chart(small_df).mark_point().encode(x="x", y="y")
    line = fr.Chart(small_df).mark_line().encode(x="x", y="y")
    svg = (scatter + line).show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_chart_add_different_data_renders():
    """Chart + Chart with different DataFrames should diagonal-concat and render."""
    df1 = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    df2 = pl.DataFrame({"x": [3.0, 4.0], "y2": [5.0, 6.0]})
    scatter = fr.Chart(df1).mark_point().encode(x="x", y="y")
    line = fr.Chart(df2).mark_line().encode(x="x", y="y2")
    # Should not raise; null-padded diagonal concat
    svg = (scatter + line).show_svg()
    assert "<svg" in svg


def test_chart_no_encoding_produces_svg(small_df):
    """A chart with mark but no encoding should produce SVG without crash."""
    # mark_point with no encode — render input may be degenerate but should not panic
    chart = fr.Chart(small_df).mark_point()
    try:
        svg = chart.show_svg()
        assert "<svg" in svg
    except Exception:
        pass  # allowed — no encoding is genuinely incomplete


def test_to_spec_json_round_trip(small_df):
    """to_spec → to_json → from_json → to_json should preserve key fields."""
    spec = fr.Chart(small_df).mark_point().encode(x="x", y="y").to_spec()
    j1 = spec.to_json()
    from ferrum import ChartSpec
    spec2 = ChartSpec.from_json(j1)
    j2 = spec2.to_json()
    d1 = json.loads(j1)
    d2 = json.loads(j2)
    assert d1["mark"] == d2["mark"]
    assert d1.get("encoding", {}).get("x") == d2.get("encoding", {}).get("x")
    assert d1.get("encoding", {}).get("y") == d2.get("encoding", {}).get("y")


def test_facet_col_produces_valid_svg(small_df):
    """Faceted chart (col=) should produce SVG with viewBox."""
    df = small_df.with_columns(pl.Series("g", ["a", "a", "b", "b", "b"]))
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").facet(col="g")
    svg = chart.show_svg()
    assert "<svg" in svg
    assert 'viewBox' in svg
    assert "NaN" not in svg


def test_facet_row_col_produces_valid_svg():
    """Two-way facet (row= and col=) should produce valid SVG."""
    df = pl.DataFrame({
        "x": [1.0, 2.0, 3.0, 4.0],
        "y": [1.0, 2.0, 1.0, 2.0],
        "r": ["r1", "r1", "r2", "r2"],
        "c": ["c1", "c2", "c1", "c2"],
    })
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").facet(row="r", col="c")
    svg = chart.show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_properties_width_height_stored():
    """properties(width=..., height=...) should store the values on the chart."""
    df = pl.DataFrame({"x": [1.0], "y": [1.0]})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").properties(width=300, height=200)
    assert chart._width == 300
    assert chart._height == 200


def test_chart_immutable_fluent_chain(small_df):
    """Each fluent method should return a new Chart; the original should be unchanged."""
    base = fr.Chart(small_df).mark_point()
    encoded = base.encode(x="x", y="y")
    # base should not have encoding channels
    assert "x" not in base._encoding
    assert "x" in encoded._encoding


