def test_pairplot_single_variable_raises_or_renders():
    """pairplot with only one variable should either render or raise a clear error."""
    df = pl.DataFrame({"a": [1.0, 2.0, 3.0], "cat": ["x", "y", "z"]})
    try:
        rc = fr.pairplot(df, vars=["a"])
        assert hasattr(rc, "row")
    except (ValueError, Exception):
        pass  # acceptable


def test_pairplot_20_panel_grid_does_not_raise():
    """pairplot with many variables (5x5 = 25 panels) should not crash at build time."""
    import numpy as np
    rng = pl.Series
    data = {f"v{i}": list(range(1, 11)) for i in range(5)}
    df = pl.DataFrame(data)
    rc = fr.pairplot(df, vars=[f"v{i}" for i in range(5)])
    assert len(rc.row) == 5
    assert len(rc.column) == 5


def test_chart_layer_method_adds_layers():
    """Chart.layer(*layers) should add layers and set layered mode."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    from ferrum.layer import Layer
    from ferrum.encoding import X, Y
    ly = Layer(mark="line", encoding={"x": X("x"), "y": Y("y")})
    chart = fr.Chart(df).mark_point().encode(x="x", y="y").layer(ly)
    assert chart._layers is not None


def test_chart_hconcat_produces_two_panels(small_df):
    """left | right should produce an HConcatChart with 2 children."""
    from ferrum.composition import HConcatChart
    left = fr.Chart(small_df).mark_point().encode(x="x", y="y")
    right = fr.Chart(small_df).mark_bar().encode(x="x", y="y")
    hc = left | right
    assert isinstance(hc, HConcatChart)
    assert len(hc.charts) == 2


def test_layered_chart_add_warns_on_theme_conflict():
    """Chart + Chart where rhs has a different theme should emit UserWarning."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    from ferrum.themes import Theme
    lhs = fr.Chart(df).mark_point().encode(x="x", y="y")
    rhs = fr.Chart(df).mark_line().encode(x="x", y="y").theme(Theme(mark_color="red"))
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        _ = lhs + rhs
        assert any(issubclass(warning.category, UserWarning) for warning in w)


