def test_to_spec_has_no_empty_viewbox(small_df):
    """SVG output should contain a non-empty viewBox attribute."""
    svg = fr.Chart(small_df).mark_point().encode(x="x", y="y").show_svg()
    assert 'viewBox="' in svg
    # viewBox must not be the empty string
    idx = svg.index('viewBox="')
    end = svg.index('"', idx + len('viewBox="'))
    viewbox_val = svg[idx + len('viewBox="'):end]
    assert viewbox_val.strip() != ""


def test_to_spec_mark_stored_correctly(small_df):
    """to_spec() should reflect the exact mark name set via mark_*."""
    spec = fr.Chart(small_df).mark_bar().encode(x="x", y="y").to_spec()
    d = json.loads(spec.to_json())
    assert d["mark"] == "bar"


def test_lmplot_spec_has_layers(small_df):
    """lmplot should produce a layered spec with at least 2 layers."""
    chart = fr.lmplot(small_df, x="x", y="y", show_metrics=False)
    d = json.loads(chart.to_spec().to_json())
    assert d.get("layers") is not None
    assert len(d["layers"]) >= 2


def test_displot_kde_svg_has_no_nan(small_df):
    """displot(kind='kde') SVG must not contain literal 'NaN' in path d attributes."""
    svg = fr.displot(small_df, x="x", kind="kde").show_svg()
    assert "<svg" in svg
    assert "NaN" not in svg


def test_catplot_box_svg_has_rect_and_rule(cat_df):
    """catplot(kind='box') SVG should contain rect marks (box) and rule marks (whiskers)."""
    svg = fr.catplot(cat_df, x="group", y="val", kind="box").show_svg()
    assert "<svg" in svg
    assert "<rect" in svg or "<line" in svg  # at minimum some geometric mark


def test_heatmap_annot_svg_has_text_elements(wide_df):
    """heatmap(annot=True) SVG should include <text elements for cell annotations."""
    svg = fr.heatmap(wide_df, annot=True).show_svg()
    assert "<svg" in svg
    assert "<text" in svg
